{
  "name": "EMCO/ETS 2090 位置控制器",
  "name_en": "EMCO/ETS 2090 Positioner Controller",
  "manufacturer": "ETS-Lindgren (formerly EMCO)",
  "description": "这是一种用于电磁兼容与天线测试系统的位置控制器，用于控制位置器或扫描机构的运动、目标位置、行程上下限以及垂直/水平极化切换。它常见于电波暗室或自动化测试平台中，用来驱动天线塔、扫描装置或类似运动平台完成定位与扫动。",
  "description_en": "This is a positioner controller used in EMC and antenna test systems to control motion, target position, travel limits, and vertical/horizontal polarization selection. It is commonly used in anechoic chambers or automated test setups to drive antenna masts, scanning mechanisms, or similar motion platforms for positioning and sweeps.",
  "actions": [
    {
      "action_name": "auto-moving",
      "description": "获取设备是否正在运动",
      "description_en": "Get whether the device is moving"
    },
    {
      "action_name": "auto-device_type",
      "description": "获取设备类型",
      "description_en": "Get the device type"
    },
    {
      "action_name": "auto-limit_upper",
      "description": "获取或设置上限位置",
      "description_en": "Get or set the upper position limit"
    },
    {
      "action_name": "auto-limit_lower",
      "description": "获取或设置下限位置",
      "description_en": "Get or set the lower position limit"
    },
    {
      "action_name": "auto-polarization",
      "description": "获取或设置极化方向",
      "description_en": "Get or set the polarization orientation"
    },
    {
      "action_name": "auto-sweep_up",
      "description": "执行向上扫动",
      "description_en": "Perform an upward sweep"
    },
    {
      "action_name": "auto-sweep_down",
      "description": "执行向下扫动",
      "description_en": "Perform a downward sweep"
    },
    {
      "action_name": "auto-target_seek",
      "description": "移动到目标位置",
      "description_en": "Move to the target position"
    },
    {
      "action_name": "auto-target",
      "description": "获取或设置目标位置",
      "description_en": "Get or set the target position"
    },
    {
      "action_name": "auto-position",
      "description": "获取当前位置",
      "description_en": "Get the current position"
    },
    {
      "action_name": "auto-local",
      "description": "切换回本地控制",
      "description_en": "Return to local control"
    },
    {
      "action_name": "auto-sequence",
      "description": "按位置序列运行",
      "description_en": "Run a sequence of positions"
    }
  ],
  "tag_hints": [
    "EMC testing",
    "antenna positioner",
    "position controller",
    "polarization switching",
    "anechoic chamber automation",
    "motion sweep",
    "travel limits"
  ]
}

